{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx swizzle",
    "description": "Copy component source for customization",
    "usage": "astryx swizzle [options] [component]",
    "options": [
      {
        "flags": "--output <dir>",
        "description": "Output directory",
        "defaultValue": "./components/astryx"
      },
      {
        "flags": "--package <pkg>",
        "description": "Scope to a specific owning package. Use @astryxdesign/core to copy an original replaced by an integration component"
      },
      {
        "flags": "--list",
        "description": "List the swizzlable Core components, including any that an integration component replaces"
      },
      {
        "flags": "-f, --overwrite",
        "description": "Replace the component's existing files. Without it, existing files fail the command with ERR_FILE_EXISTS and nothing is written. A helper an earlier swizzle wrote is reused when it is the same and is never replaced by a copy that carries it: a different one stays, and this copy writes its own under a version-suffixed name. Swizzling the component whose folder holds that helper counts it as one of that component's own files. A changed private attribute owner module, or a style module it imports, fails the command without --overwrite and is replaced with it"
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
